@Test @MainActor
func 補足付きイベントを保存して再読込しても花名を保つ() async throws {
    let store = TitleLifecycleTranscriptStore()
    let (vm, client) = makeCodexVM(transcriptStore: store)
    try await vm.startNew(approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    try await vm.sendText("/review", submit: true)
    let userID = try #require(firstUserMessageID(vm))
    let threadID = try #require(vm.threadId)
    try await yieldUserItem(client, threadId: threadID, itemJSON: unidentifiedSupplementJSON(id: userID))
    try await waitUntil {
        vm.transcript.contains {
            if case .userMessage(let id, let text, _, _) = $0 {
                return id == userID && text == "/review\nログイン画面を修正"
            }
            return false
        }
    }
    #expect(vm.titleState.source == .flower)
    await vm.flushTranscriptNow()
    await vm.restore(threadId: threadID, approvalPolicy: .named("on-request"), sandbox: .named("workspace-write"))
    #expect(vm.titleState == .generated(flowerName: "Rose"))
    await vm.terminate()
}

// DashboardFeatureTests内の追加検査案（未実走）。load内のhookで競合順序を固定する。
@MainActor private final class FirstLoadHookStore: SessionStoreProtocol {
    var live = SessionTitleState.generated(flowerName: "Rose")
    var stored: [PersistedSessionDescriptor] = []
    var snapshots: [[PersistedSessionDescriptor]] = []
    var onFirstLoad: (() -> Void)?
    func load() async -> [PersistedSessionDescriptor] {
        let hook = onFirstLoad
        onFirstLoad = nil
        hook?()
        return stored
    }
    func save(_ sessions: [PersistedSessionDescriptor]) async throws {
        snapshots.append(sessions)
        stored = sessions
    }
}
@Test(arguments: [false, true]) @MainActor
func 初回load中の変更と削除を反映する(delete: Bool) async {
    let store = FirstLoadHookStore()
    let coordinator = SessionPersistenceCoordinator(sessionStore: store, projectStore: InMemoryProjectStore(), logError: { _, _ in })
    let id = SessionID()
    coordinator.liveTitleState = { _ in store.live }
    store.onFirstLoad = {
        if delete {
            coordinator.removeSession(id)
        } else {
            store.live = store.live.renamed(to: "通知を修正")
            coordinator.persistSessionName(id: id, name: "通知を修正")
        }
    }
    coordinator.persistSession(PersistedSessionDescriptor(id: id, kind: .claudeCode, workingDirectory: "/tmp/work", name: "Rose", projectID: nil, startedAt: Date(), command: "/bin/cat", args: [], env: [:], titleSource: .flower, flowerName: "Rose"))
    await coordinator.waitForPendingWrites()
    if delete {
        #expect(store.snapshots.allSatisfy { !$0.contains { $0.id == id } })
    } else {
        #expect(store.snapshots.first?.first?.name == "通知を修正")
        #expect(store.snapshots.first?.first?.titleSource == .manual)
    }
}

// AcceptanceSessionTitlePersistenceTests.swiftの既存ヘルパーを使用する追加検査案（未実走）。
@Test @MainActor
func チャットの明示改名は一度だけ保存する() async throws {
    let store = TitlePersistenceRecordingStore()
    let (stream, _) = AsyncStream<(SessionID, HookEvent)>.makeStream()
    let dashboard = DashboardViewModel(environment: makeTestEnvironment(
        pty: MockPTYManager(), hookStream: stream, sessions: store,
        appServerClientFactory: { _, _, _, _, _ in EventYieldingStructuredClient() }
    ))
    await dashboard.start()
    let id = try await dashboard.spawnNewSession(kind: .claudeCode, backend: .appServer)
    await dashboard.waitForPendingPersistenceWritesForTesting()
    let before = await store.saveSnapshots.count
    dashboard.renameSession(id, to: "通知を修正")
    await dashboard.waitForPendingPersistenceWritesForTesting()
    #expect(await store.saveSnapshots.count == before + 1)
}

